enum class Gender {
    
    WOMAN,
    MAN,
    NONBINARY;

    


    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeGender: FfiConverterRustBuffer<Gender> {
    override fun read(buf: ByteBuffer) = try {
        Gender.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: Gender) = 4UL

    override fun write(value: Gender, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





